// Pure models and in-memory DOM. Browser/layout/touch acceptance remains NOT_RUN.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const M=require('../model.js'),UI=require('../c2.js'),{fixture}=require('./dom_fixture.cjs');
const root=path.resolve(__dirname,'..'),w={};vm.runInNewContext(fs.readFileSync(path.join(root,'data/bundle.js'),'utf8'),{window:w});
const bundle=JSON.parse(JSON.stringify(w.C2_DATA)),read=n=>JSON.parse(fs.readFileSync(path.join(root,'data',n),'utf8')),nav=M.fromBundle(bundle,'navharness'),h=M.fromBundle(bundle,'harnessvln');
let checks=0;function test(name,fn){fn();checks++;console.log('PASS '+name);}const plain=x=>JSON.parse(JSON.stringify(x));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function start(options={}){const f=fixture(options);f.c2.open('navharness',f.app.getContext());return f;}
test('two exact mappings retain legacy aliases and original59 schema',()=>{assert.deepEqual(bundle.schema,read('method.json'));assert.deepEqual(bundle.mapping,read('mapping.json'));assert.deepEqual(bundle.compat,read('analysis.compat.json'));assert.deepEqual(bundle.mappingsByPaperId.harnessvln,bundle.mapping);assert.deepEqual(bundle.mappingsByPaperId.navharness,read('navharness.mapping.json'));assert.deepEqual(M.counts(h),{original:59,instances:13,nodes:72,answers:47,unknowns:6,implementationUnknown:0,implementationVerified:0});assert.deepEqual(M.counts(nav),{original:59,instances:18,nodes:77,answers:51,unknowns:12,implementationUnknown:20,implementationVerified:0});assert.deepEqual(M.validate(h),[]);assert.deepEqual(M.validate(nav),[]);});
test('all18 explicit instances retain parent, template and expansion slot without changing original nodes',()=>{for(const n of bundle.schema.nodes){const rendered=nav.nodes.get(n.id);assert.equal(rendered.label,n.labelOriginal);assert.equal(rendered.parent,n.parentId);assert.equal(rendered.order,n.order);}for(const n of nav.mapping.expandedNodes){assert.deepEqual(nav.nodes.get(n.nodeId).source,n);assert(nav.nodes.has(n.parentId));assert(bundle.schema.nodes.some(x=>x.id===n.repeatOfSchemaNode));assert(bundle.schema.nodes.some(x=>x.id===n.expansionSlot));}assert.equal(nav.mapping.sourceVersion,'2609.34276v1');});
test('other37 remain empty and AdaptiveGoals canonical identity cannot receive NavHarness evidence',()=>{const f=fixture(),catalog=plain(f.window.PAPER_CATALOG);for(const p of catalog.papers){if(['harnessvln','navharness'].includes(p.canonical_id))continue;const m=M.fromBundle(bundle,p.canonical_id);assert.equal(m.mapping,null);assert.equal(m.answers.size,0);assert.equal(m.nodes.size,59);assert.equal(m.questions.length,0);}assert.equal(M.fromBundle(bundle,'arxiv:2609.39915').mapping,null);assert.equal(catalog.papers.length,39);});
test('all51 states and per-answer sourceKind,codeEvidence,sourceGapIds are rendered without promotion',()=>{const statuses={};for(const a of nav.answers.values()){statuses[a.status]=(statuses[a.status]||0)+1;const html=UI.drawerHtml(nav,{...M.locate(nav,M.initial(nav),a.nodeId),drawer:'evidence',drawerTab:'answer'});assert(html.includes(esc(a.answer)));assert(html.includes(esc(a.status)));assert(html.includes(esc(a.sourceKind)));for(const value of Object.values(a.codeEvidence))assert(html.includes(esc(value)));assert(html.includes('sourceGapIds'));if(!a.sourceGapIds.length)assert(html.includes('sourceGapIds：[]（无已关联缺口）'));for(const id of a.sourceGapIds){assert(html.includes('data-c2="gap" data-id="'+id+'"'));assert(nav.questions.some(q=>q.id===id));}}assert.deepEqual(statuses,{evidence_linked:43,author_claim_only:6,partially_reported:2});assert.equal(UI.nodeState(nav,[...nav.answers.values()].find(a=>a.status==='partially_reported').nodeId).startsWith('部分报告'),true);});
test('all12 unknown fields and supplied exact links render and search without fabricated node targets',()=>{const html=UI.drawerHtml(nav,{...M.initial(nav),drawer:'unresolved'});for(const q of nav.questions){for(const text of [q.id,q.topic,q.detail,q.status])assert(html.includes(esc(text)));assert(M.searchQuestions(nav,q.topic).some(x=>x.id===q.id));assert(M.searchQuestions(nav,q.id).some(x=>x.id===q.id));for(const url of q.sourceUrls||[])assert(html.includes('href="'+esc(url)+'"'));for(const id of q.evidenceRecordIds||[])assert(html.includes('data-evidence-id="'+id+'"'));const item=UI.questionHtml(q,true,nav);assert(!item.includes('data-c2="enter"'));}const u12=nav.questions.find(q=>q.id==='U12');assert(u12.detail.includes('Figure18(p39)'));assert(u12.detail.includes('多11步'));assert(html.includes('href="https://arxiv.org/pdf/2609.34276v1#page=39"'));assert(UI.questionHtml(u12,true,nav).includes('全篇问题'));});
test('724 answer source occurrences keep exact fixed versions and distinct PDF or HTML locators',()=>{let total=0;for(const a of nav.answers.values()){const html=UI.locatorsHtml(a.sourceLocators);total+=a.sourceLocators.length;assert.equal((html.match(/class="c2-source"/g)||[]).length,a.sourceLocators.length);for(const l of a.sourceLocators){assert(html.includes('href="'+esc(l.sourceUrl)+'"'));assert(html.includes(esc(l.pageOrAnchor)));assert.equal(l.sourceVersion,'2609.34276v1');}}assert.equal(total,724);});
test('31 ledger records render original attribution and false reproduction flags in paper scope',()=>{assert.deepEqual(bundle.ledgersByPaperId.navharness,read('navharness.ledger.json'));assert.equal(nav.evidence.size,31);const html=UI.ledgerHtml(nav);for(const r of nav.ledger.records){assert.equal(r.independentlyReproduced,false);for(const v of [r.evidenceRecordId,r.summaryZh,r.attribution])assert(html.includes(esc(v)));assert(html.includes('independentlyReproduced'));assert(html.includes('false'));for(const l of r.sourceLocators)assert(html.includes('href="'+esc(l.sourceUrl)+'"'));}assert.notDeepEqual(nav.evidence.get('E01'),h.evidence.get('E01'));assert(UI.ledgerHtml(nav,['E01']).includes('2609.34276v1'));assert(!UI.ledgerHtml(nav,['E01']).includes('2609.15195v3'));assert(UI.ledgerHtml(h,['E01']).includes('2609.15195v3'));});
test('every77 node is locatable with visible selected ancestry at desktop and mobile model widths',()=>{for(const width of [390,820])for(const id of nav.nodes.keys()){const s=M.locate(nav,M.initial(nav),id),scene=M.layout(nav,s,width);assert(scene.nodes.some(n=>n.id===id));for(const n of scene.nodes){assert(n.x>=0&&n.y>=0);assert(n.x+n.w<=scene.width+.01);assert(n.y+n.h<=scene.height+.01);assert.equal(n.labelLines.join(''),nav.nodes.get(n.id).label.replace(/\n/g,''));}for(const e of scene.edges)assert.equal(nav.nodes.get(e.target).parent,e.source);}for(const id of nav.nodes.keys()){let s={...M.initial(nav),focus:id},seen=[];for(let page=0;page<=M.branch(nav,s).maxPage;page++){s=M.reduce(nav,s,{type:'page',page});seen.push(...M.branch(nav,s).items.map(n=>n.id));}assert.deepEqual(seen,M.children(nav,id).map(n=>n.id));}});
test('selector reports2 mapped37 pending and opens NavHarness through all three entry routes',()=>{const f=fixture();f.app.dispatch({type:'globalTree',key:'a'});let selector=f.$('#analysis-paper-select');selector.value='navharness';selector.emit('change');assert(f.$('#global-panel-a').textContent.includes('51 回答'));assert(f.$('#global-panel-a').textContent.includes('2 篇有解析内容'));assert(f.$('#global-panel-a').textContent.includes('37 篇解析 pending'));f.click('[data-open-analysis="navharness"]');assert.equal(f.c2.getModel().answers.size,51);f.c2.returnToTrees();f.app.dispatch({type:'paper',id:'navharness'});f.app.dispatch({type:'tab',tab:'analysis'});assert(f.$('#paper-body').textContent.includes('51条回答'));f.$('#paper-body').querySelector('[data-open-analysis="navharness"]').emit('click');assert.equal(f.c2.getState().paperId,'navharness');const state={...M.initial(nav),selected:'method.module5.why',focus:'method.module5',drawer:'evidence',drawerTab:'sources'},deep=fixture({url:'https://example.test/local-only/#analysis='+encodeURIComponent(JSON.stringify(state))});assert.equal(deep.c2.getState().paperId,'navharness');assert.equal(deep.c2.getState().selected,state.selected);assert.equal(deep.c2.getState().drawerTab,'sources');});
test('source gap opens actual U02 and preserves all12 unknowns plus keyboard close focus',()=>{const f=start(),a=[...nav.answers.values()].find(a=>a.codeEvidence.status==='not_reviewed_implementation_unknown');f.c2.dispatch({type:'enter',id:a.nodeId});f.c2.dispatch({type:'drawer',drawer:'evidence'});f.click('[data-c2="gap"][data-id="U02"]');assert.equal(f.c2.getState().drawer,'unresolved');assert.equal(f.c2.getState().questionId,'U02');assert.equal(f.$('#c2-app').querySelectorAll('.c2-question').length>=12,true);assert.equal(f.document.activeElement.id,'c2-unknown-navharness-U02');f.document.activeElement.emit('keydown',{key:'Escape'});assert.equal(f.c2.getState().drawer,null);assert.equal(f.document.activeElement.id,UI.domId(nav,'node',a.nodeId));});
test('U12 searchable without node backlink and cleared search restores full nodes',()=>{const f=start();f.c2.dispatch({type:'search',query:'U12'});assert(f.$('.c2-unknown-search').textContent.includes('Case2 task34'));f.click('[data-c2="gap"][data-id="U12"]');assert.equal(f.c2.getState().questionId,'U12');assert(f.$('#c2-unknown-navharness-U12').textContent.includes('全篇问题'));f.c2.dispatch({type:'search',query:'no-such-answer-record'});assert(f.$('.c2-empty'));f.click('[data-c2="clear-search"]');assert.equal(f.$$('.c2-directory-row').filter(n=>n.dataset.c2!=='gap').length,77);});
test('repeated open is no-op, gap history restores identity and paper switch scopes scroll',()=>{const f=start();f.window.scrollY=290;const length=f.historyStack.length;f.c2.open('navharness',f.app.getContext());assert.equal(f.historyStack.length,length);assert.equal(f.window.scrollY,290);f.c2.dispatch({type:'gap',id:'U12'});f.$('#c2-drawer-body').scrollTop=153;f.c2.dispatch({type:'gap',id:'U02'});f.$('#c2-drawer-body').scrollTop=287;f.back();assert.equal(f.c2.getState().questionId,'U12');assert.equal(f.$('#c2-drawer-body').scrollTop,153);f.forward();assert.equal(f.$('#c2-drawer-body').scrollTop,287);f.c2.dispatch({type:'close'});f.back();assert.equal(f.c2.getState().questionId,'U02');assert.equal(f.$('#c2-drawer-body').scrollTop,287);f.forward();assert.equal(f.c2.getState().drawer,null);f.c2.open('harnessvln',f.app.getContext());assert.equal(f.c2.getModel().answers.size,47);assert.equal(f.c2.getModel().questions.length,6);f.back();assert.equal(f.c2.getState().paperId,'navharness');assert.equal(f.c2.getModel().questions.length,12);});
test('catalog/tree facet,query,page,paper,scroll context restore after NavHarness',()=>{const f=fixture();f.app.dispatch({type:'facet',facet:'representation'});f.app.dispatch({type:'search',query:'NavHarness'});f.app.dispatch({type:'paper',id:'navharness'});f.app.dispatch({type:'tab',tab:'analysis'});f.window.scrollY=441;f.$('#paper-body').scrollTop=82;const before=plain(f.app.getState());f.$('#paper-body').querySelector('[data-open-analysis="navharness"]').emit('click');f.c2.returnToTrees();assert.deepEqual(plain(f.app.getState()),before);assert.equal(f.window.scrollY,441);assert.equal(f.$('#paper-body').scrollTop,82);});
test('mutation controls reject reduced unknowns,changed states,broken gaps,cross-paper ledger',()=>{for(const mutate of [b=>b.mappingsByPaperId.navharness.unresolvedQuestions.pop(),b=>b.mappingsByPaperId.navharness.answers[0].status='author_claim_only',b=>b.mappingsByPaperId.navharness.answers[0].sourceGapIds=['U99'],b=>b.ledgersByPaperId.navharness.paperId='harnessvln']){const b=plain(bundle);mutate(b);assert(M.validate(M.fromBundle(b,'navharness')).length>0);}});
test('NavHarness77 keyboard targets,modal tab cycle,tabs and Escape preserve paper identity',()=>{const f=start({width:390,mobile:true});f.click('[data-atlas-mode="analysis"]');assert.equal(f.$('#c2-app').querySelectorAll('.atlas-vertex').length,77);for(const [i,id] of [...nav.nodes.keys()].entries()){let target=f.$('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="'+id+'"]');assert(target);target.focus();target.emit('keydown',{key:i%2?'Enter':' '});assert.equal(f.c2.getState().selected,id);assert.equal(f.c2.getState().paperId,'navharness');assert.equal(f.$('#c2-app').querySelectorAll('.atlas-vertex').filter(n=>n.getAttribute('tabindex')==='0').length,1);}f.c2.dispatch({type:'enter',id:'method.module5.why'});f.c2.dispatch({type:'drawer',drawer:'evidence'});for(const [key,tab] of [['ArrowRight','sources'],['End','scope'],['Home','answer']]){f.$('#c2-tab-'+f.c2.getState().drawerTab).emit('keydown',{key});assert.equal(f.c2.getState().drawerTab,tab);assert.equal(f.document.activeElement.id,'c2-tab-'+tab);}const controls=f.$('#c2-overlay').querySelectorAll('button, a[href], input, select, textarea, [tabindex="0"]').filter(x=>!x.disabled);controls.at(-1).focus();controls.at(-1).emit('keydown',{key:'Tab'});assert.equal(f.document.activeElement,controls[0]);controls[0].emit('keydown',{key:'Tab',shiftKey:true});assert.equal(f.document.activeElement,controls.at(-1));controls.at(-1).emit('keydown',{key:'Escape'});assert.equal(f.c2.getState().drawer,null);assert.equal(f.document.activeElement.id,'c2-node-navharness-method_module5_why');});
